import sys
import json
from functools import lru_cache
from typing import List

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        start = end = -1
        full_mask = 0
        for r in range(rows):
            for c in range(cols):
                value = grid[r][c]
                pos = r * cols + c
                if value != -1:
                    full_mask |= 1 << pos
                if value == 1:
                    start = pos
                elif value == 2:
                    end = pos

        @lru_cache(maxsize=None)
        def dfs(pos: int, mask: int) -> int:
            if pos == end:
                return 1 if mask == full_mask else 0
            r, c = divmod(pos, cols)
            total = 0
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    nxt = nr * cols + nc
                    bit = 1 << nxt
                    if (full_mask & bit) and not (mask & bit):
                        total += dfs(nxt, mask | bit)
            return total

        return dfs(start, 1 << start)

