#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static int R, C, K;
static int *cellId;
static int endId;
static int fullMask;
static int *memo;

static int dfs(int **grid, int pos, int mask) {
    if (pos == endId) return mask == fullMask ? 1 : 0;
    size_t stride = (size_t)1u << K;
    size_t index = (size_t)pos * stride + (size_t)mask;
    if (memo[index] != -1) return memo[index];

    int r = -1, c = -1;
    for (int rr = 0; rr < R; ++rr) {
        for (int cc = 0; cc < C; ++cc) {
            if (cellId[rr * C + cc] == pos) { r = rr; c = cc; break; }
        }
        if (r != -1) break;
    }

    int total = 0;
    const int dr[4] = {1, -1, 0, 0};
    const int dc[4] = {0, 0, 1, -1};
    for (int d = 0; d < 4; ++d) {
        int nr = r + dr[d], nc = c + dc[d];
        if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
        int nextId = cellId[nr * C + nc];
        if (nextId < 0) continue;
        int bit = 1 << nextId;
        if ((mask & bit) == 0) total += dfs(grid, nextId, mask | bit);
    }
    memo[index] = total;
    return total;
}

int uniquePathsIII(int **grid, int gridSize, int *gridColSize) {
    R = gridSize;
    C = gridColSize[0];
    cellId = (int *)malloc((size_t)R * C * sizeof(int));
    if (!cellId) return 0;
    for (int i = 0; i < R * C; ++i) cellId[i] = -1;

    int startId = -1;
    endId = -1;
    K = 0;
    for (int r = 0; r < R; ++r) {
        for (int c = 0; c < C; ++c) {
            if (grid[r][c] != -1) {
                cellId[r * C + c] = K;
                if (grid[r][c] == 1) startId = K;
                else if (grid[r][c] == 2) endId = K;
                ++K;
            }
        }
    }

    fullMask = (1 << K) - 1;
    size_t stride = (size_t)1u << K;
    memo = (int *)malloc((size_t)K * stride * sizeof(int));
    if (!memo) { free(cellId); return 0; }
    for (size_t i = 0; i < (size_t)K * stride; ++i) memo[i] = -1;

    int result = dfs(grid, startId, 1 << startId);
    free(memo);
    free(cellId);
    return result;
}

int main(void) {
    char input[4096];
    size_t len = fread(input, 1, sizeof(input) - 1, stdin);
    input[len] = '\0';

    int grid[20][20];
    int *rows[20];
    int cols[20] = {0};
    int depth = 0, rowCount = 0, currentCol = 0;
    for (size_t i = 0; i < len;) {
        if (input[i] == '[') {
            ++depth;
            if (depth == 3) currentCol = 0;
            ++i;
        } else if (input[i] == ']') {
            if (depth == 3) { cols[rowCount] = currentCol; ++rowCount; }
            --depth;
            ++i;
        } else if (depth == 3 && (input[i] == '-' || isdigit((unsigned char)input[i]))) {
            int sign = 1;
            if (input[i] == '-') { sign = -1; ++i; }
            int value = 0;
            while (i < len && isdigit((unsigned char)input[i])) {
                value = value * 10 + (input[i] - '0');
                ++i;
            }
            grid[rowCount][currentCol++] = sign * value;
        } else {
            ++i;
        }
    }
    for (int r = 0; r < rowCount; ++r) rows[r] = grid[r];

    int result = uniquePathsIII(rows, rowCount, cols);
    printf("%d\n", result);
    return 0;
}

