import java.io.*;
import java.util.*;

class Solution {
    private int rows;
    private int cols;
    private int end;
    private int fullMask;
    private final Map<Long, Integer> memo = new HashMap<>();

    public int uniquePathsIII(int[][] grid) {
        rows = grid.length;
        cols = grid[0].length;
        int start = -1;
        end = -1;
        fullMask = 0;
        memo.clear();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = grid[r][c];
                int pos = r * cols + c;
                if (value != -1) fullMask |= (1 << pos);
                if (value == 1) start = pos;
                else if (value == 2) end = pos;
            }
        }
        return dfs(start, 1 << start);
    }

    private int dfs(int pos, int mask) {
        if (pos == end) return mask == fullMask ? 1 : 0;
        long key = (((long) mask) << 5) | pos;
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int r = pos / cols;
        int c = pos % cols;
        int total = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            int nxt = nr * cols + nc;
            int bit = 1 << nxt;
            if ((fullMask & bit) != 0 && (mask & bit) == 0) {
                total += dfs(nxt, mask | bit);
            }
        }
        memo.put(key, total);
        return total;
    }
}

public class Main {
    private static int[][] parseGrid(String s) {
        List<int[]> rows = new ArrayList<>();
        List<Integer> current = null;
        int depth = 0;
        int i = 0;
        while (i < s.length()) {
            char ch = s.charAt(i);
            if (ch == '[') {
                depth++;
                if (depth == 3) current = new ArrayList<>();
                i++;
            } else if (ch == ']') {
                if (depth == 3 && current != null) {
                    int[] row = new int[current.size()];
                    for (int j = 0; j < current.size(); j++) row[j] = current.get(j);
                    rows.add(row);
                    current = null;
                }
                depth--;
                i++;
            } else if (depth == 3 && (ch == '-' || Character.isDigit(ch))) {
                int sign = 1;
                if (ch == '-') { sign = -1; i++; }
                int value = 0;
                while (i < s.length() && Character.isDigit(s.charAt(i))) {
                    value = value * 10 + (s.charAt(i) - '0');
                    i++;
                }
                current.add(sign * value);
            } else {
                i++;
            }
        }
        return rows.toArray(new int[0][]);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[][] grid = parseGrid(line);
        System.out.println(new Solution().uniquePathsIII(grid));
    }
}

